INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Community Law and Mediation is celebrating 50th anniversary', 'community-law-and-mediation-is-celebrating-50th-anniversary', '<p>The Community Law and Mediation organisation, which was started in Coolock, Dublin, is celebrating its 50th anniversary this year.</p>
<p>The organisation was established by the Free Legal Advice Centres, better known as FLAC, in 1975, and was modelled on an American neighbourhood law centre. Initially set up as the Coolock Community Law Centre, it achieved its core aim of designing a blueprint for how a community model of civil legal aid could be rolled out nationally.</p>
<p>Over the five decades, it evolved from a local to a national service with physical locations in Coolock and Limerick and new areas of work in mediation, environmental justice (see opposite) and children’s law.</p>
<p>In Limerick alone, CLM now provides support, advice, advocacy and more to 750 people a year.</p>
<p>Community Law and Mediation, as it is today known, began its 50th anniversary celebrations with a human rights event in February at Dublin City Hall. It featured a public discussion of human rights issues today with Bernadette Devlin McAliskey, social justice and human rights campaigner; Michael O’Flaherty, Council of Europe Commissioner for Human Rights; climate justice lawyer Tessa Khan; and Rose Wall, outgoing CEO of Community Law &amp; Mediation.</p>
<p>The discussion was a fine way to show CLM’s intent to continue to fight for fairness, justice and human rights in our communities.</p>
<p><strong>To find out further CLM anniversary events later this year, visit:</strong> <a href="https://communitylawandmediation.ie/">https://communitylawandmediation.ie/</a></p>', 'The Community Law and Mediation organisation, which was started in Coolock, Dublin, is celebrating its 50th anniversary this year. The organisation was established by the Free Legal Advice Centres, better known as FLAC, in 1975, and was modelled on an American neighbourhood law centre. Initially set up as the Coolock Community Law Centre, it achieved', 'https://changingireland.ie/wp-content/uploads/2025/07/CLM-50-years-Bernadette-Devlin-McAliskey-social-justice-and-human-rights-campaigner-with-Pers-B.jpg', '', '[{"slug":"equality-rights","title":"Equality & Rights"}]', '[]', '', 255210, 1, '2025-07-11T14:00:40Z', '2025-07-11T16:41:31Z', '2025-07-11T14:00:40Z')
