INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Cherry Orchard players switch to water, saving money, saving planet', 'cherry-orchard-players-switch-to-water-saving-money-saving-planet', '<p>Cherry Orchard FC also received Uisce Cliste recommendations for their tuck-shop, educational materials and nine face-to-face education sessions for children, adolescents and adults.</p>
<p>Following this, hydration-related knowledge and habits improved among children and parents by 17% and over 900 litres of water were drunk during the short study period. Startlingly, there was a 97% reduction in usage by players of single use plastic bottles, aluminium cans and coffee cups.</p>
<p>Launching the report, Jennifer Murnane O’Connor, Minister of State at the Department of Health, said, “This report reinforces that <strong>access to clean drinking water is </strong>not only <strong>a basic right</strong>, but a powerful lever for improving public health. Through authentic community collaboration and targeted interventions, we can support education and find solutions to community challenges. With evidence-based policy we can enhance the built environment to make healthy choices much easier in order to improve health, reduce waste and advance health equity across disadvantaged areas.”</p>
<p>Stephen O&#8217;Brien, underage chairperson at Cherry Orchard FC said he was proud of the Uisce Cliste project because the practical measures “<strong>allowed us to make a real impact on the health of our members.”</strong></p>
<p>Joanna Kelly works with Dublin City Council as its local development officer for Cherry Orchard Ballyfermot and she was Uisce Cliste’s project leader. She said the report shows “the real impact of working directly with communities and stakeholders to design meaningful, evidence-informed interventions. It highlights how public realm improvements, combined with education, can drive positive long-term health outcomes in our neighbourhoods.”</p>
<figure aria-describedby="caption-attachment-255119"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/06/Adolescents-attending-a-water-and-nutrition-education-session.jpg" alt="" width="2048" height="1536" srcset="https://changingireland.ie/wp-content/uploads/2025/06/Adolescents-attending-a-water-and-nutrition-education-session.jpg 2048w, https://changingireland.ie/wp-content/uploads/2025/06/Adolescents-attending-a-water-and-nutrition-education-session-300x225.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/06/Adolescents-attending-a-water-and-nutrition-education-session-1024x768.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/06/Adolescents-attending-a-water-and-nutrition-education-session-768x576.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/06/Adolescents-attending-a-water-and-nutrition-education-session-1536x1152.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/06/Adolescents-attending-a-water-and-nutrition-education-session-1080x810.jpg 1080w" sizes="(max-width: 2048px) 100vw, 2048px" /><figcaption><em>• Adolescents attending a water and nutrition education session.</em></figcaption></figure>
<p>The research for the report was conducted by Dr. Grace O’Malley, Dr. Desire Naigaga, Dr. Angela Hickey, Dr. Lisa Mellon and Prof. Suzanne McDonough of RCSI University of Medicine and Health Sciences. The project was a collaborative effort between RCSI University of Medicine and Health Sciences, Dublin City Council, and the Sláintecare Healthy Communities Programme, as part of the Dublin City Healthy Ireland Strategy 2022–2025, funded by the Department of Health.</p>
<p><strong>To find out more, visit: </strong><a href="https://healthyhydration.eu/"><em>https://healthyhydration.eu/</em></a></p>
<p>* You can read the 46-page Uisce Cliste report here: <a href="https://indd.adobe.com/view/794f33f2-ea57-49b2-9e93-14a5bfbb4c62"><em>https://indd.adobe.com/view/794f33f2-ea57-49b2-9e93-14a5bfbb4c62</em></a></p>
<blockquote><p><a href="https://changingireland.ie/free-public-water-should-be-available-everywhere-argues-grace-omalley/">Free public water should be available everywhere, argues Grace O&#8217;Malley</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Free public water should be available everywhere, argues Grace O’Malley” — Changing Ireland" src="https://changingireland.ie/free-public-water-should-be-available-everywhere-argues-grace-omalley/embed/#?secret=Be0cjGsKMG#?secret=yBXT4AIQpV" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'A study into how increasing safe public drinking water and tailored education can improve the health of people living in disadvantaged areas, was launched in April. The ‘Uisce Cliste: Healthy Hydration for Dublin’ report tells how better access to free high quality drinking water in public spaces changes habits and awareness about the importance of drinking water. A secondary aim was to explore how well an Uisce Cliste project with Cherry Orchard FC, in Ballyfermot, where the report was…', 'https://changingireland.ie/wp-content/uploads/2025/06/The-Uisce-Cliste-project-team-with-Jennifer-Murnane-OConnor-Minister-of-State-at-the-Department-of-Health-scaled.jpg', '', '[{"slug":"health","title":"Health"}]', '[{"slug":"ballyfermot","title":"Ballyfermot"}]', '', 255114, 1, '2025-06-13T15:56:29Z', '2025-06-13T16:06:02Z', '2025-06-13T15:56:29Z')
