INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Falcarragh volunteers are helping war-weary refugees from Ukraine', 'falcarragh-volunteers-are-helping-war-weary-refugees-from-ukraine', '<p>“Everyone has been so helpful to us over our last two years here in Donegal,” said Victoria Moreva, from Mariupol, who is a doctor of chemistry and was professor at the university there. “My husband Alexander, my daughter, Victoria, and I were twice displaced from our homes by the war. We had to flee from Donetsk first and then driven out of Mariupol two years ago by Russian aggression. Since moving here, I’ve been very lucky to conduct research at the Cill Ulta organic centre.”</p>
<p>Alexander, a construction engineer, said he’s also lucky: “I’m very excited, having just started a new job this week in Dunlewey as an environmental officer.”</p>
<figure aria-describedby="caption-attachment-255177"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/07/•-A-group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal.jpg" alt="" width="1536" height="1391" srcset="https://changingireland.ie/wp-content/uploads/2025/07/•-A-group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/07/•-A-group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-300x272.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/07/•-A-group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-1024x927.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/07/•-A-group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-768x696.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/07/•-A-group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-1080x978.jpg 1080w" sizes="(max-width: 1536px) 100vw, 1536px" /><figcaption><em>• A group attending a Fáilte Isteach meeting in Falcarragh, Co. Donegal.</em></figcaption></figure>
<p>Oleh Sobol, who fled from the Black Sea port of Odessa after being bombed by Russians, said Pobail Le Chéile’s initiative eases his loneliness. “The English speaking club is very important to me. It gives me a chance to talk to local people. I don&#8217;t feel so lonely when I have the group to look forward to.”</p>
<p>Sonja Wilson from Leeds, who has lived in west Donegal for 18 months and worked as a nurse for more than 30 years in paediatric cardiology, at a children&#8217;s hospice and in a school for children with profound medical needs, explained why she is a project volunteer.</p>
<p>“Many years ago my mother was a refugee and because she and her family were welcomed in Germany, they went on to live happy, fulfilled lives. I believe as human beings we are all stronger when we stand together. I have learned a lot from my Ukrainian friends and my life is so much richer for knowing them. I hope what we do helps them feel welcomed and valued.”</p>
<figure aria-describedby="caption-attachment-255176"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/07/•-Group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-scaled.jpg" alt="" width="2560" height="1920" srcset="https://changingireland.ie/wp-content/uploads/2025/07/•-Group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2025/07/•-Group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-300x225.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/07/•-Group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-1024x768.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/07/•-Group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-768x576.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/07/•-Group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-1536x1152.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/07/•-Group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-2048x1536.jpg 2048w, https://changingireland.ie/wp-content/uploads/2025/07/•-Group-attending-a-Failte-Isteach-meeting-in-Falcarragh-Co.-Donegal-1080x810.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /><figcaption><em>• Having a cup of tea at a Fáilte Isteach meeting in Falcarragh, Co. Donegal.</em></figcaption></figure>
<p>Maggie Maclean, a retired midwife from Ontario, Canada, said, “I have first-hand experience living in a country where I didn’t speak the language so I wanted to help our Ukrainian friends adapt to their new life. Every week I come away with my spirits uplifted because of the joy, determination and tenacity of these lovely people who have experienced and lost so much. It’s a privilege to share time with them.”</p>
<p>Joan Sweeney, from Philadelphia, said, “I really appreciate all the work Pobail Le Chéile has done, especially the weekly Ukrainian conversation group. I understand how difficult it can be navigating a new country, especially challenging when you don’t speak the language. Our little group assists our Ukrainian friends with a myriad of needs &#8211; from completing important paperwork to making shopping lists. Sometimes just having a stress-free cup of tea and making new friends makes a world of difference.”</p>
<p>More volunteers are welcome. Phone: (074) 918 0111.</p>
<p><strong>This article appeared in our Spring 2025 edition, alongside other stories on integration and refugees (eg click below to see what they are doing in Carlow). </strong><strong>You can read <a href="https://changingireland.ie/wp-content/uploads/2025/05/Issue-88-Spring-2025-Changing-Ireland-32p.pdf">the full Spring 2025 edtition HERE</a> (free to read/download).</strong></p>
<p><strong><em>*Sean Hillen is an author and former foreign correspondent for The Irish Times. He is also co-founder of Ireland Writing Retreat in rural Donegal and the Wild Atlantic Writing Awards (WAWA).</em></strong></p>
<blockquote><p><a href="https://changingireland.ie/food-brings-people-together-volunteers-carlow-prove/">Food brings people together, as volunteers in Carlow prove</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Food brings people together, as volunteers in Carlow prove” — Changing Ireland" src="https://changingireland.ie/food-brings-people-together-volunteers-carlow-prove/embed/#?secret=pISFTjW9MH#?secret=i2cPUVAXJ6" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'Men, women and children desperately escaping the war in Ukraine have found a warm home-away-from home in Cloughaneely. Every week, Fáilte Isteach Falcarragh hosted by the local community centre, Pobail Le Chéile, attracts a multi-national group of volunteers to help these war-weary refugees improve their English-language skills under a project that promotes greater integration and a deeper sense of community spirit by forging new friendships and facilitating learning about different cultures.', 'https://changingireland.ie/wp-content/uploads/2025/07/•-An-Ukrainian-woman-attending-a-Failte-Isteach-in-Falcarragh-Co.-Donegal.jpg', '', '[{"slug":"refugees-ukraine","title":"Refugees/Ukraine"}]', '[]', '', 255174, 1, '2025-06-09T09:47:31Z', '2025-07-09T10:29:26Z', '2025-06-09T09:47:31Z')
