INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Ace jockey Cathy Gannon has advice for aspiring jockeys from Limerick', 'ace-jockey-cathy-gannon-has-advice-for-aspiring-jockeys-from-limerick', '<p>Cathy had 450 wins in a remarkable career spanning 4,500 races.</p>
<p>“That’s ten percent,” she said proudly as youngsters looked at her agog. “I had a good time of it. I worked hard, it needs a good work ethic,” she said.</p>
<p>She was well placed to empathise with the teenagers who gathered in Clonshire Equestrian Centre outside Adare, Co. Limerick.</p>
<p>“I used to love horses and wasn&#8217;t very good at school. I used to ride the pony down to school and tie it up outside,” she recalled.</p>
<p>“We just wish we had a place somewhere like this in Dublin when we were starting, you know. This is great, great facilities, great for the kids,” she said.</p>
<p>“It&#8217;s not all about being a jockey, you could be a stable hand, or a rider, a farrier, a vet, a physio, or a dentist &#8211; there&#8217;s lots of work in horses,” added Cathy.</p>
<div><iframe title="Ace jockey Cathy Gannon has advice for aspiring jockeys from Limerick" width="696" height="392" src="https://www.youtube.com/embed/in3UQ3Jrl5Y?feature=oembed&#038;enablejsapi=1" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>
<p>Of course, the youngsters almost all want to be jockeys. One of MYA’s graduates Terry Casey recorded his first win as a jockey at Roscommon on May 12 and, among others, he made sure to thank Moyross jockey Wesley Joyce, also a graduate of MYA, for his support as his career takes off.</p>
<p>In Clonshire, the aspiring youngsters – male and female &#8211; got a real feel for what it’s like to be a thoroughbred racehorse jockey because Niall Byrnes from the Racing Academy and Centre of Education (RACE) brought a simulator to Limerick for the occasion.</p>
<p>Tommy O&#8217;Donnell from Ballinacurra Weston and Crescent College Comprehensive was reluctant to mount the machine: “It’s a horse with no legs,” he said. Afterwards, he said he would like to go again and he hopes to follow others on training visits to Kildare.</p>
<figure aria-describedby="caption-attachment-254926"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-1-scaled.jpg" alt="" width="2560" height="1619" srcset="https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-1-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-1-300x190.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-1-1024x647.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-1-768x486.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-1-1536x971.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-1-2048x1295.jpg 2048w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-1-1080x683.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /><figcaption><em>• Participants in the Limerick Equine Education and Therapeutic Programme pictured on horseback at Clonshire Equestrian Centre, on May 20, 2025. Photo by Tony Grehan. </em></figcaption></figure>
<p>Nathan Devereux, who joined Moyross Youth Academy’s programme when he was in fourth class in Corpus Christi Primary School, and is now a student in Thomond Community College, has been up to Kildare where RACE is based.</p>
<p>“You experience the speed on a racetrack and what it&#8217;s like to be around thoroughbreds and how to tack them up and what to do with thoroughbreds. It’s a good experience up there,” he said.</p>
<p><figure aria-describedby="caption-attachment-254924"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-40-scaled.jpg" alt="" width="2560" height="1707" srcset="https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-40-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-40-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-40-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-40-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-40-1536x1024.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-40-2048x1365.jpg 2048w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-40-1080x720.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /><figcaption><em>• Participants in the Limerick Equine Education and Therapeutic Programme pictured in Clonshire Equestrian Centre, on May 20, 2025. Photo by Tony Grehan. See <a href="https://www.facebook.com/permalink.php?story_fbid=pfbid0jkkCzeNy3NCWf5zhGpdiLSLLsMt4DpcpxUUZmGh5DoBNtQxXgLpiquJaHQQs8iXgl&amp;id=100064871220884&amp;__cft__[0]=AZUO95IVM_yYnr2zQwzB706aeXlG4270fdTnTnx8PAfQ-acUo8CHHCsCB1UjdFaYEg-WCkN9lkct8aPifGw8Z4mq5SEHcPey83DinLAdFixeH3nBOFUh5tuZqmju5tWDUCbO-TZ9GS80nuWzb1a6Omm1X5fUhJwX6_24w4BNNIFH4LCJ1-r0L6HrnJSUXJ9qEKNsKk43EghU-QH5jF9kR-lU&amp;__tn__=%2CO%2CP-R">all Tony&#8217;s photos from the day at this link</a>. </em></figcaption></figure>Moyross Youth Academy (MYA) oversees a project it calls the Limerick Equine, Education and Therapeutic Programme (LEETP) which connects with and educates children from five secondary and seven primary schools in Limerick city. The plan is to bring the youngsters together again over the summer.</p>
<p>Andrew O’Byrne, MYA’s development manager, said, “We’re grateful to Cathy Gannon and all volunteers and staff and to Clonshire Equestrian Centre for their support on the day.”</p>
<p>MYA staff present in Clonshire included Damien Gavin, Tony Carey, John Quinlivan, Catherine Normoyle, and chef Eoin Ruane who works in MYA as a tutor and who provided a barbeque.</p>
<p>The horse industry and local government were represented by Stephanie Scully, education officer with Horseracing Ireland, and Tommy Barrett from the regeneration office of Limerick City and County Council.</p>
<p>Also present were teaching staff from the five secondary schools involved, namely Crescent College Comprehensive, St. Clement&#8217;s College, St. Munchin&#8217;s College, Thomond Community College, and CBS Sexton Street.</p>
<p><figure aria-describedby="caption-attachment-254925"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-41-scaled.jpg" alt="" width="2560" height="1707" srcset="https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-41-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-41-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-41-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-41-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-41-1536x1024.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-41-2048x1365.jpg 2048w, https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-41-1080x720.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /><figcaption><em>• Participants in the Limerick Equine Education and Therapeutic Programme pictured in Clonshire Equestrian Centre, on May 20, 2025. Photo by Tony Grehan. See <a href="https://www.facebook.com/permalink.php?story_fbid=pfbid0jkkCzeNy3NCWf5zhGpdiLSLLsMt4DpcpxUUZmGh5DoBNtQxXgLpiquJaHQQs8iXgl&amp;id=100064871220884&amp;__cft__[0]=AZUO95IVM_yYnr2zQwzB706aeXlG4270fdTnTnx8PAfQ-acUo8CHHCsCB1UjdFaYEg-WCkN9lkct8aPifGw8Z4mq5SEHcPey83DinLAdFixeH3nBOFUh5tuZqmju5tWDUCbO-TZ9GS80nuWzb1a6Omm1X5fUhJwX6_24w4BNNIFH4LCJ1-r0L6HrnJSUXJ9qEKNsKk43EghU-QH5jF9kR-lU&amp;__tn__=%2CO%2CP-R">all Tony&#8217;s photos from the day at this link</a>. </em></figcaption></figure>Moyross Youth Academy is funded by the Department of Justice and the LEETP project is funded through the Department of Agriculture, Food and the Marine, in conjunction with Limerick City and County Council’s Economic and Social Intervention Fund (ESIF), with support from Limerick and Clare Education and Training Board (LCETB).</p>
<p>MYA also delivers a programme at primary school level and one of the schools was represented by Liam Kelly from Corpus Christi Primary School as part of the therapeutic element of the programme. As part of the primary schools element, MYA has five ponies based with John and Marie Burke of Clare Equestrian Centre in Doora, Barefield, Co. Clare. They have been a strong supporter of the project and its development since 2007.</p>
<p>Long-terms plans include setting up an employment programme for young people from Limerick interested in finding work in the horse industry – which is why Horse Racing Ireland and the LCETB are involved.</p>
<h3><strong><em>See <a href="https://www.facebook.com/permalink.php?story_fbid=pfbid0jkkCzeNy3NCWf5zhGpdiLSLLsMt4DpcpxUUZmGh5DoBNtQxXgLpiquJaHQQs8iXgl&amp;id=100064871220884&amp;__cft__[0]=AZUO95IVM_yYnr2zQwzB706aeXlG4270fdTnTnx8PAfQ-acUo8CHHCsCB1UjdFaYEg-WCkN9lkct8aPifGw8Z4mq5SEHcPey83DinLAdFixeH3nBOFUh5tuZqmju5tWDUCbO-TZ9GS80nuWzb1a6Omm1X5fUhJwX6_24w4BNNIFH4LCJ1-r0L6HrnJSUXJ9qEKNsKk43EghU-QH5jF9kR-lU&amp;__tn__=%2CO%2CP-R">all Tony Grehan&#8217;s photos from the day at this link</a>. </em></strong></h3>
<figure aria-describedby="caption-attachment-254939"><a href="https://www.facebook.com/permalink.php?story_fbid=pfbid0jkkCzeNy3NCWf5zhGpdiLSLLsMt4DpcpxUUZmGh5DoBNtQxXgLpiquJaHQQs8iXgl&amp;id=100064871220884&amp;__cft__%5B0%5D=AZXSvUN11rRUEzw9WqeihGDdLK79N5hr5DAvAGE4OjWeHhE45Mo2xD6NgnVApM3eK-vLPOXHVt_fL38NT7iWfze_AZm-ne2vTdhu9hNoiuW_s01MLh7VcO3lM96ZhVchKMkn9Nrrm83ItfHE065qIv1LHUNC2Ubxc7cGGtcIt90ukj7DPW_-VMnAFnEQ3FQwfm3zjWUYIWIiBhhjNNQwbe6j&amp;__tn__=%2CO%2CP-R"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/05/See-all-Tonys-photos-from-the-day-at-this-link.png" alt="" width="613" height="626" srcset="https://changingireland.ie/wp-content/uploads/2025/05/See-all-Tonys-photos-from-the-day-at-this-link.png 613w, https://changingireland.ie/wp-content/uploads/2025/05/See-all-Tonys-photos-from-the-day-at-this-link-294x300.png 294w, https://changingireland.ie/wp-content/uploads/2025/05/See-all-Tonys-photos-from-the-day-at-this-link-24x24.png 24w, https://changingireland.ie/wp-content/uploads/2025/05/See-all-Tonys-photos-from-the-day-at-this-link-48x48.png 48w" sizes="(max-width: 613px) 100vw, 613px" /></a><figcaption>• See all Tony&#8217;s photos from the day at this link.</figcaption></figure>
<blockquote><p><a href="https://changingireland.ie/voices-from-the-saddle-back-moyross-youth-academy-all-the-way/">Voices from the saddle back Moyross Youth Academy all the way</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Voices from the saddle back Moyross Youth Academy all the way” — Changing Ireland" src="https://changingireland.ie/voices-from-the-saddle-back-moyross-youth-academy-all-the-way/embed/#?secret=b0D3PeNQqt#?secret=WH3Y5asiV7" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<blockquote><p><a href="https://changingireland.ie/moyross-youth-academy-participants/">3 people who had life-changing experiences with Moyross Youth Academy</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“3 people who had life-changing experiences with Moyross Youth Academy” — Changing Ireland" src="https://changingireland.ie/moyross-youth-academy-participants/embed/#?secret=YRFZDp7DZN#?secret=Fj8SZSVJdN" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<blockquote><p><a href="https://changingireland.ie/moyross-youth-academy-launch/">Is new Youth Academy proof Moyross has turned a corner?</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Is new Youth Academy proof Moyross has turned a corner?” — Changing Ireland" src="https://changingireland.ie/moyross-youth-academy-launch/embed/#?secret=D3Annp6qAA#?secret=agCsN94fWX" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', '“Work hard” if you want to make your dreams come true of working in the equestrian industry. This is the message to youngsters from former champion jockey Cathy Gannon who gave her time on Tuesday to travel down from Dublin to meet 30 aspiring young jockeys in Limerick. This is National Volunteering Week and she was joined by other volunteers on the day – Michael O’Kelly, a founding member of the Limerick Equine Education and Therapeutic Programme (LEETP) and photographer Tony Grehan.', 'https://changingireland.ie/wp-content/uploads/2025/05/Changing-Ireland-MYA-May-20-2025-photo-by-Tony-Grehan-38-scaled.jpg', '', '[{"slug":"inclusion-editors-choice","title":"Inclusion (Editor’s Choice)"}]', '[{"slug":"cathy-gannon","title":"Cathy Gannon"},{"slug":"cbs-sexton-street","title":"CBS Sexton Street"},{"slug":"crescent-college-comprehensive","title":"Crescent College Comprehensive"},{"slug":"department-of-agriculture-food-and-the-marine","title":"Department of Agriculture Food and the Marine"},{"slug":"department-of-justice","title":"Department of Justice"},{"slug":"horse-racing-ireland","title":"Horse Racing Ireland"},{"slug":"limerick-and-clare-education-and-training-board","title":"Limerick and Clare Education and Training Board"},{"slug":"limerick-city-and-county-council","title":"Limerick City and County Council"},{"slug":"limerick-equine-education-and-therapeutic-programme","title":"Limerick Equine Education And Therapeutic Programme"},{"slug":"moyross-youth-academy","title":"Moyross Youth Academy"},{"slug":"racing-academy-and-centre-of-education","title":"Racing Academy and Centre of Education"},{"slug":"st-clements-college","title":"St. Clement''s College"},{"slug":"st-munchins-college","title":"St. Munchin''s College"},{"slug":"thomond-community-college","title":"Thomond Community College"},{"slug":"tony-grehan","title":"Tony Grehan"}]', '', 254914, 1, '2025-05-23T09:36:29Z', '2025-07-11T16:41:26Z', '2025-05-23T09:36:29Z')
