INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Film producers seek couples for A Ring and a Prayer on RTE', 'multicultural-couples-sought-for-series-on-rte', '<p>Producer Peter Kelly feels the show touches on an important new social reality:</p>
<blockquote><p>&#8220;The series is celebrating multicultural couples getting married, which is a feature of modern Irish society, we all know that. We&#8217;re used to people from different communities and ethnic groups in our workplaces and in our neighbourhoods, but when they get married, they are coming into our families. That&#8217;s the new phenomenon. Going by the CSO statistics, nearly one in four marriages has at least one nationality other than Irish.&#8221;</p></blockquote>
<figure aria-describedby="caption-attachment-254896"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/05/Greg-and-Vaidehi-from-ARAAP-Series1-Ep2.jpg" alt="" width="1371" height="1920" srcset="https://changingireland.ie/wp-content/uploads/2025/05/Greg-and-Vaidehi-from-ARAAP-Series1-Ep2.jpg 1371w, https://changingireland.ie/wp-content/uploads/2025/05/Greg-and-Vaidehi-from-ARAAP-Series1-Ep2-214x300.jpg 214w, https://changingireland.ie/wp-content/uploads/2025/05/Greg-and-Vaidehi-from-ARAAP-Series1-Ep2-731x1024.jpg 731w, https://changingireland.ie/wp-content/uploads/2025/05/Greg-and-Vaidehi-from-ARAAP-Series1-Ep2-768x1076.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/05/Greg-and-Vaidehi-from-ARAAP-Series1-Ep2-1097x1536.jpg 1097w, https://changingireland.ie/wp-content/uploads/2025/05/Greg-and-Vaidehi-from-ARAAP-Series1-Ep2-1080x1512.jpg 1080w" sizes="(max-width: 1371px) 100vw, 1371px" /><figcaption><em>• Greg and Vaidehi from Series 1-Episode 2.</em></figcaption></figure>
<p>He feels the series has a positive message about integration.</p>
<blockquote><p>&#8220;There&#8217;s a lesson for the whole of society in this. Two people falling in love from very different backgrounds, that&#8217;s a living, breathing symbol of people overcoming any sense of prejudice. With our series we&#8217;re trying to make sure that people are talking about &#8216;us&#8217; rather than &#8216;them&#8217; all the time. This is us, this is Irish society, this is the way we are now and let&#8217;s try and make it normal.</p>
<p>&#8220;The second thing to say about it is in the name, it&#8217;s about a ring and a prayer. We&#8217;re looking at people getting married, but it&#8217;s also an opportunity to learn about their religious heritage, their faith background and cultural traditions. We&#8217;re trying to prioritise examples of weddings where people bring their religious heritage, their faith background or cultural practices into the ceremony itself.&#8221;</p></blockquote>
<p>Anyone interested in taking part should email <a href="mailto:ringprayer@esras.com">ringprayer@esras.com</a></p>
<p>The six part TV series will broadcast on RTÉ One in early 2026.</p>
<p>Esra Films researcher Ingrid urged people to spread the word:</p>
<blockquote><p>&#8220;If you or someone you know is getting married soon, and you’d like to be considered for participation in this heartwarming documentary series, we would love to hear from you,&#8221; she said.</p></blockquote>
<p>You can in the meantime watch the previous series which is available to view <a href="https://www.rte.ie/player/series/a-ring-and-a-prayer/10002728-00-0000?epguid=IP000067568">here on the RTE Player</a>.</p>
<p>&nbsp;</p>', 'So, what happens when couples from different cultures and faith traditions decide to get married? Esras Films is looking at exactly that for the second series of its show A Ring and a Prayer due to be filmed this year and broadcast in 2026. Currently, it is appealing for couples, at least one of whom is not Irish, to come forward. They must be planning their wedding ceremony for this year.', 'https://changingireland.ie/wp-content/uploads/2025/05/Cassandra-and-Sam-a-couple-from-the-first-series-ARAAP-Ep-1-scaled.jpg', '', '[{"slug":"family-support","title":"Family Support"}]', '[{"slug":"integration","title":"integration"}]', '', 254888, 1, '2025-05-13T13:31:52Z', '2025-05-13T17:44:08Z', '2025-05-13T13:31:52Z')
