INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Galway groups launch employer toolkits to boost inclusive employment', 'galway-groups-launch-employer-toolkits-to-boost-inclusive-employment', '<p>Speaking in Galway city, <strong>Minister Naughton</strong> said, “Projects funded under the WorkAbility Programme incorporate a strong focus on employer engagement, raising employers’ awareness and building their capacity to recruit, retain and progress people with disabilities in their workforce.”</p>
<p>She commended all involved in developing the toolkits saying they had “risen to the challenge of the programme in a very relevant and unique”.</p>
<div><iframe title="We&amp;apos;re supporting people with a disability and also employers - Hildegarde Naughton speaking today" width="696" height="392" src="https://www.youtube.com/embed/iLrHEAQkenY?feature=oembed&#038;enablejsapi=1" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>
<p>The toolkits highlights practical ways that employers can benefit from a more inclusive and innovative workplace.</p>
<p>Both publications were funded through the Department of Social Protection’s WorkAbility &#8211; Inclusive Pathways to Employment Programme. It previously supported the launch of a toolkit designed for County Roscommon.</p>
<figure aria-describedby="caption-attachment-254847"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/03/GCP-WorkAbility-toolkit.png" alt="" width="577" height="433" srcset="https://changingireland.ie/wp-content/uploads/2025/03/GCP-WorkAbility-toolkit.png 577w, https://changingireland.ie/wp-content/uploads/2025/03/GCP-WorkAbility-toolkit-300x225.png 300w" sizes="(max-width: 577px) 100vw, 577px" /><figcaption>• GCP&#8217;s WorkAbility toolkit.</figcaption></figure>
<p>Changing Ireland attended the city launch organised by Galway City Partnership where the Mayor of Galway, <strong>Peter Keane</strong>, urged everyone present to recommit themselves to inclusion. He described the toolkit as “a fantastic achievement” and said Galway County Council “stood foursquare behind everything you’re trying to do in Galway City Partnership”.</p>
<figure aria-describedby="caption-attachment-254845"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/03/IMG_0043-scaled-e1743184647959.jpg" alt="Staff and participants in the WorkAbility programme: Amy McGrath, programme mentor, Ali Loughnane, Maggie Woods, programme co-ordinatory, Brian Clancy, Esther Koroma, Eanna O’Cosgora and Lisa Madden." width="2048" height="1472" srcset="https://changingireland.ie/wp-content/uploads/2025/03/IMG_0043-scaled-e1743184647959.jpg 2048w, https://changingireland.ie/wp-content/uploads/2025/03/IMG_0043-scaled-e1743184647959-300x216.jpg 300w, https://changingireland.ie/wp-content/uploads/2025/03/IMG_0043-scaled-e1743184647959-1024x736.jpg 1024w, https://changingireland.ie/wp-content/uploads/2025/03/IMG_0043-scaled-e1743184647959-768x552.jpg 768w, https://changingireland.ie/wp-content/uploads/2025/03/IMG_0043-scaled-e1743184647959-1536x1104.jpg 1536w, https://changingireland.ie/wp-content/uploads/2025/03/IMG_0043-scaled-e1743184647959-1080x776.jpg 1080w" sizes="(max-width: 2048px) 100vw, 2048px" /><figcaption>• Staff and participants in the WorkAbility programme: Amy McGrath, programme mentor, Ali Loughnane, Maggie Woods, programme co-ordinatory, Brian Clancy, Esther Koroma, Eanna O’Cosgora and Lisa Madden.</figcaption></figure>
<p>The toolkit launch was attended by many with direct experience of hitting barriers to the workplace. They described not only their experience, but the loss to businesses and society in general when people’s potential is denied.</p>
<p><strong>Lisa Madden</strong> was one who shared her workplace story.</p>
<p>“Meeting with the team on WorkAbility has given me a strength I didn’t think I had. I can stand up for myself particularly in work situations and even have been able to take on extra hours,” she said.</p>
<figure aria-describedby="caption-attachment-254848"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2025/03/People-with-experience-of-seeking-employment-told-their-stories-including-how-finding-work-changed-their-lives-scaled.jpeg" alt="" width="2560" height="1920" srcset="https://changingireland.ie/wp-content/uploads/2025/03/People-with-experience-of-seeking-employment-told-their-stories-including-how-finding-work-changed-their-lives-scaled.jpeg 2560w, https://changingireland.ie/wp-content/uploads/2025/03/People-with-experience-of-seeking-employment-told-their-stories-including-how-finding-work-changed-their-lives-300x225.jpeg 300w, https://changingireland.ie/wp-content/uploads/2025/03/People-with-experience-of-seeking-employment-told-their-stories-including-how-finding-work-changed-their-lives-1024x768.jpeg 1024w, https://changingireland.ie/wp-content/uploads/2025/03/People-with-experience-of-seeking-employment-told-their-stories-including-how-finding-work-changed-their-lives-768x576.jpeg 768w, https://changingireland.ie/wp-content/uploads/2025/03/People-with-experience-of-seeking-employment-told-their-stories-including-how-finding-work-changed-their-lives-1536x1152.jpeg 1536w, https://changingireland.ie/wp-content/uploads/2025/03/People-with-experience-of-seeking-employment-told-their-stories-including-how-finding-work-changed-their-lives-2048x1536.jpeg 2048w, https://changingireland.ie/wp-content/uploads/2025/03/People-with-experience-of-seeking-employment-told-their-stories-including-how-finding-work-changed-their-lives-1080x810.jpeg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /><figcaption>• People with experience of seeking employment told their stories, including how finding work changed their lives.</figcaption></figure>
<p><strong>Maggie Woods</strong> of Galway City Partnership encouraged employers to use the toolkit,</p>
<p>“Being part of this programme, you are building an inclusive workplace and this is  also a strategic advantage. Employers who hire individuals with disabilities are guaranteed to see increased productivity, creativity, and employee loyalty.”</p>
<p>Summing up its value, she said the toolkit “provides practical, step-by-step resources to help you implement inclusive hiring practices. Whether you&#8217;re just starting or looking to enhance your efforts, this guide will support you every step of the way.”</p>
<p>Programme partners in the development of the city’s toolkit include Galway City Partnership, Galway Chamber of Commerce, Galway Roscommon Education &amp; Training Board, EmployAbility Galway, Access for All and Brothers of Charity Western Region.</p>
<p>The Workability &#8211; Inclusive Pathways to Employment Programme is co-funded by the Government and the EU.</p>
<p>The toolkits are available from Galway City Partnership (email &#8211; <a href="mailto:info@gcp.ie">info@gcp.ie</a> / tel. 091-773 466) and through FORUM Connemara (email &#8211; <a href="mailto:info@forumconnemara.ie?" target="_blank" rel="noopener">info@forumconnemara.ie</a> / tel. 095-41116.</p>
<p>&nbsp;</p>', 'Employers in Galway city and county are to benefit from the launch today of new employment toolkits to assist companies and organisations to recruit, retain and respect those with disabilities in the workforce. The toolkits were launched simultaneously in Galway city and county today by Hildegarde Naughton, minister of state with responsibility for disability.', 'https://changingireland.ie/wp-content/uploads/2025/03/IMG_5860-scaled.jpeg', '• Maggie Woods of Galway City Partnership and Mayor of Galway, Peter Keane at the launch.', '[{"slug":"income-employment","title":"Income & Employment"}]', '[{"slug":"department-of-social-protection","title":"Department of Social Protection"},{"slug":"forum-connemara","title":"FORUM Connemara"},{"slug":"galway-city-partnership","title":"Galway City Partnership"},{"slug":"hildegarde-naughton","title":"Hildegarde Naughton"},{"slug":"workability","title":"WorkAbility"}]', '', 254841, 1, '2025-03-28T17:00:51Z', '2025-03-28T17:57:38Z', '2025-03-28T17:00:51Z')
