INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Salary increases in early years education and childcare welcomed by SIPTU', 'salary-increases-in-early-years-education-and-childcare-welcomed-by-siptu', '<p>SIPTU has welcomed €45 million extra in Budget 2025 to raise pay for workers in the early years education and childcare sector.<br />
Avril Green, an early years educator and union leader said: “This marks progress in our fight for better pay and recognition. Low wages push passionate educators away. We’re moving in the right direction.”</p>
<p>SIPTU&#8217;s head of strategic organising, Darragh O’Connor, said: “Thanks to our activists and members, the government now sees low pay as a big issue in Early Years. Minister O’Gorman has boosted pay investment. This is to be commended. Now, we urge Early Years employers to negotiate a new pay deal without delay.”</p>
<p>Minister Roderic O’Gorman confirmed the increase in his Budget 2025 speech on October 2, saying: “This would be the third successive pay increase for the sector, and hopefully sets out a clear pathway for further increases.”</p>
<p>SIPTU members have highlighted for years how low pay was creating a staffing crisis in the early years education and childcare sector. Managers and staff have struggled financially and services are under continual pressure with children, parents and communities losing out.</p>
<p>Early Childhood Ireland wants pay parity with primary school teachers for early years professionals. Its policy director Frances Byrne said, “Despite thousands of students participating in degree-level Early Years courses each year, we hear too many stories of graduates pursuing careers elsewhere because their prospects of working in Early Years and School Age Care settings are still quite poor.”</p>
<p>She noted that while some political parties proposed to reduce fees for parents this is unfeasible without a stable workforce. An independent review estimates that up to 20,000 additional staff will be needed by 2028.</p>', 'SIPTU has welcomed €45 million extra in Budget 2025 to raise pay for workers in the early years education and childcare sector.', 'https://changingireland.ie/wp-content/uploads/2024/11/SIPTU-EARLY-YEARS.jpg', '', '[{"slug":"income-employment","title":"Income & Employment"}]', '[{"slug":"early-childhood-ireland","title":"Early Childhood Ireland"},{"slug":"early-years-education","title":"Early Years Education"},{"slug":"siptu","title":"siptu"}]', '', 254688, 1, '2024-12-02T15:45:19Z', '2024-11-29T01:38:32Z', '2024-12-02T15:45:19Z')
